/**
 * @suppress
 */
public object FfiConverterTypeCndEngine: FfiConverter<CndEngine, Pointer> {

    override fun lower(value: CndEngine): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): CndEngine {
        return CndEngine(value)
    }

    override fun read(buf: ByteBuffer): CndEngine {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: CndEngine) = 8UL

    override fun write(value: CndEngine, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



data class AiCommandContext (
    /**
     * Channel currently playing, used by "next", "previous" and "go back".
     */
    var `playingStableHash`: kotlin.String?, 
    /**
     * Category on screen, a relevance hint only.
     */
    var `groupTitle`: kotlin.String?, 
    /**
     * UI language such as `fr-FR`; the short reply is written in it.
     */
    var `locale`: kotlin.String
) {
    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAiCommandContext: FfiConverterRustBuffer<AiCommandContext> {
    override fun read(buf: ByteBuffer): AiCommandContext {
        return AiCommandContext(
            FfiConverterOptionalString.read(buf),
            FfiConverterOptionalString.read(buf),
            FfiConverterString.read(buf),
        )
    }

    override fun allocationSize(value: AiCommandContext) = (
            FfiConverterOptionalString.allocationSize(value.`playingStableHash`) +
            FfiConverterOptionalString.allocationSize(value.`groupTitle`) +
            FfiConverterString.allocationSize(value.`locale`)
    )

    override fun write(value: AiCommandContext, buf: ByteBuffer) {
            FfiConverterOptionalString.write(value.`playingStableHash`, buf)
            FfiConverterOptionalString.write(value.`groupTitle`, buf)
            FfiConverterString.write(value.`locale`, buf)
    }
}



data class AiCommandResult (
    var `action`: AiAction, 
    /**
     * 0 to 5 channels to offer when the request is ambiguous or the provider failed.
     */
    var `alternatives`: List<IptvItemRecord>, 
    var `reply`: kotlin.String, 
    /**
     * `"local"`, `"gemini"`, `"openai_compatible"` or `"anthropic"`.
     */
    var `resolvedBy`: kotlin.String, 
    var `latencyMs`: kotlin.ULong, 
    var `fallbackReason`: kotlin.String?
) {
    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAiCommandResult: FfiConverterRustBuffer<AiCommandResult> {
    override fun read(buf: ByteBuffer): AiCommandResult {
        return AiCommandResult(
            FfiConverterTypeAiAction.read(buf),
            FfiConverterSequenceTypeIptvItemRecord.read(buf),
            FfiConverterString.read(buf),
            FfiConverterString.read(buf),
            FfiConverterULong.read(buf),
            FfiConverterOptionalString.read(buf),
        )
    }

    override fun allocationSize(value: AiCommandResult) = (
            FfiConverterTypeAiAction.allocationSize(value.`action`) +
            FfiConverterSequenceTypeIptvItemRecord.allocationSize(value.`alternatives`) +
            FfiConverterString.allocationSize(value.`reply`) +
            FfiConverterString.allocationSize(value.`resolvedBy`) +
            FfiConverterULong.allocationSize(value.`latencyMs`) +
            FfiConverterOptionalString.allocationSize(value.`fallbackReason`)
    )

    override fun write(value: AiCommandResult, buf: ByteBuffer) {
            FfiConverterTypeAiAction.write(value.`action`, buf)
            FfiConverterSequenceTypeIptvItemRecord.write(value.`alternatives`, buf)
            FfiConverterString.write(value.`reply`, buf)
            FfiConverterString.write(value.`resolvedBy`, buf)
            FfiConverterULong.write(value.`latencyMs`, buf)
            FfiConverterOptionalString.write(value.`fallbackReason`, buf)
    }
}



data class AiProviderConfig (
    var `kind`: AiProviderKind, 
    /**
     * Empty means "use the provider's default".
