            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceTypeRecoShelf.allocationSize(value.`shelves`)
            )
        }
        is AppleRerankStart.Ask -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeAppleRerankRequest.allocationSize(value.`request`)
            )
        }
    }

    override fun write(value: AppleRerankStart, buf: ByteBuffer) {
        when(value) {
            is AppleRerankStart.Skip -> {
                buf.putInt(1)
                Unit
            }
            is AppleRerankStart.Cached -> {
                buf.putInt(2)
                FfiConverterSequenceTypeRecoShelf.write(value.`shelves`, buf)
                Unit
            }
            is AppleRerankStart.Ask -> {
